const allLeads = $input.all();
const now = new Date();
const yesterday = new Date(now.getTime() - 86400000);
const last7days = new Date(now.getTime() - 7 * 86400000);

// Filter leads from last 24 hours
const todayLeads = allLeads.filter(item => {
  const ts = new Date(item.json.Timestamp);
  return ts >= yesterday;
});

// All leads for 7-day trend
const weekLeads = allLeads.filter(item => {
  const ts = new Date(item.json.Timestamp);
  return ts >= last7days;
});

// Score breakdown today
const hot  = todayLeads.filter(l => parseInt(l.json.Score) >= 8).length;
const warm = todayLeads.filter(l => parseInt(l.json.Score) >= 5 && parseInt(l.json.Score) < 8).length;
const cold = todayLeads.filter(l => parseInt(l.json.Score) < 5).length;

// Source breakdown today
const sourceCounts = {};
todayLeads.forEach(l => {
  const src = l.json.Source || 'Unknown';
  sourceCounts[src] = (sourceCounts[src] || 0) + 1;
});
const sourceBreakdown = Object.entries(sourceCounts)
  .sort((a,b) => b[1]-a[1])
  .map(([s,c]) => `${s}: ${c}`).join(', ');

// Follow-up pending (all time, not sent)
const followupPending = allLeads.filter(l => l.json['Followup Sent'] === 'FALSE').length;

// 7-day average
const dailyAvg = (weekLeads.length / 7).toFixed(1);

// Top industries today
const industryCounts = {};
todayLeads.forEach(l => {
  const ind = l.json.Industry || 'Unknown';
  industryCounts[ind] = (industryCounts[ind] || 0) + 1;
});
const topIndustries = Object.entries(industryCounts)
  .sort((a,b) => b[1]-a[1]).slice(0,3)
  .map(([i,c]) => `${i} (${c})`).join(', ');

// Average score today
const avgScore = todayLeads.length > 0
  ? (todayLeads.reduce((sum, l) => sum + (parseInt(l.json.Score) || 0), 0) / todayLeads.length).toFixed(1)
  : 0;

const todaySummary = todayLeads.map(l =>
  `• ${l.json.Name} (${l.json.Business}) — Score: ${l.json.Score}/10 — ${l.json.Intent} — ${l.json.Message?.substring(0, 80)}...`
).join('\n');

return [{
  json: {
    totalToday: todayLeads.length,
    hot, warm, cold,
    avgScore,
    sourceBreakdown: sourceBreakdown || 'No leads today',
    topIndustries: topIndustries || 'N/A',
    followupPending,
    weekTotal: weekLeads.length,
    dailyAvg,
    totalAllTime: allLeads.length,
    todaySummary: todaySummary || 'No leads in the last 24 hours.',
    reportDate: now.toDateString()
  }
}];

